import{_ as a,H as r,f as t,i as s}from"./chunks/framework.B3xCVCEH.js";const u=JSON.parse('{"title":"Links and References","description":"","frontmatter":{},"headers":[],"relativePath":"dev/links-and-references/index.md","filePath":"dev/links-and-references/README.md"}'),o={name:"dev/links-and-references/index.md"};function n(i,e,l,c,h,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="links-and-references" tabindex="-1">Links and References <a class="header-anchor" href="#links-and-references" aria-label="Permalink to &quot;Links and References&quot;">​</a></h1><h2 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h2><p>Most CaSS-related tools will be found on our organization&#39;s <a href="https://github.com/cassproject" target="_blank" rel="noreferrer">GitHub</a>.</p><p>CaSS itself can be located in this <a href="https://github.com/cassproject/CASS" target="_blank" rel="noreferrer">GitHub Repo</a>.</p><h2 id="cass-installation-bash-script" tabindex="-1">CaSS Installation Bash Script <a class="header-anchor" href="#cass-installation-bash-script" aria-label="Permalink to &quot;CaSS Installation Bash Script&quot;">​</a></h2><p>An installation script for Linux systems can be found <a href="https://raw.githubusercontent.com/cassproject/CASS/master/scripts/cassInstall.sh" target="_blank" rel="noreferrer">here</a>. Check out the Installation guide for more help.</p><h2 id="cass-project-website" tabindex="-1">CaSS Project Website <a class="header-anchor" href="#cass-project-website" aria-label="Permalink to &quot;CaSS Project Website&quot;">​</a></h2><p>The primary CaSS website may be found at:</p><p><a href="http://cassproject.org/" target="_blank" rel="noreferrer">cassproject.org</a></p><h2 id="cass-library-api" tabindex="-1">CaSS Library API <a class="header-anchor" href="#cass-library-api" aria-label="Permalink to &quot;CaSS Library API&quot;">​</a></h2><p>The CaSS Library API allows you to work with data within a CaSS instance. It&#39;s highly recommended to use Node.js along with our NPM package.</p><ul><li><a href="https://github.com/cassproject/cass-npm" target="_blank" rel="noreferrer">NPM</a> | <a href="https://github.com/cassproject/CASS/tree/master/src/main/js/cass" target="_blank" rel="noreferrer">GitHub</a> | <a href="https://cdn.jsdelivr.net/gh/cassproject/cass@master/src/main/js/cass.js" target="_blank" rel="noreferrer">CDN</a></li><li><a href="http://cassproject.github.io/CASS/docs/modules/org.cassproject.html" target="_blank" rel="noreferrer">Documentation</a>.</li></ul><h2 id="cass-schema" tabindex="-1">CaSS Schema <a class="header-anchor" href="#cass-schema" aria-label="Permalink to &quot;CaSS Schema&quot;">​</a></h2><p>A &#39;schema&#39; describes the organization/structure of a set of data.</p><p>The schema for CaSS objects is documented <a href="http://schema.cassproject.org/" target="_blank" rel="noreferrer">here</a>, listing the data associated with each CaSS object. CaSS is built upon the pre-existing work done at <a href="https://schema.org/" target="_blank" rel="noreferrer">Schema.org</a></p><h2 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h2><p>The sandbox is a public site hosting a CaSS instance where you may try CaSS without setting up a CaSS instance yourself, along with a CaSS Editor for easy viewing and editting. There are two sandboxes:</p><ul><li><a href="https://sandbox.cassproject.org/" target="_blank" rel="noreferrer">Latest stable version</a></li><li><a href="https://dev.cassproject.org/" target="_blank" rel="noreferrer">Latest unstable version</a></li></ul><h2 id="other-learning-resources" tabindex="-1">Other Learning Resources <a class="header-anchor" href="#other-learning-resources" aria-label="Permalink to &quot;Other Learning Resources&quot;">​</a></h2><p>The following links are helpful resources for already-existing tools that CaSS utilizes, written by others:</p><ul><li>ElasticSearch Simple Query String <ul><li><a href="https://www.elastic.co/guide/index.html" target="_blank" rel="noreferrer">Documentation</a></li><li><a href="https://www.elastic.co/guide/en/elasticsearch/reference/5.6/query-dsl-simple-query-string-query.html" target="_blank" rel="noreferrer">Tutorial 1</a> | <a href="https://logz.io/blog/elasticsearch-queries/" target="_blank" rel="noreferrer">Tutorial 2</a></li></ul></li><li>JSON-LD <ul><li><a href="https://json-ld.org/" target="_blank" rel="noreferrer">Website</a></li><li><a href="http://www.linkeddatatools.com/introduction-json-ld" target="_blank" rel="noreferrer">Tutorial</a></li></ul></li></ul><h2 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact Us&quot;">​</a></h2><p>Request access to the <a href="https://docs.google.com/a/eduworks.com/forms/viewform?bc=transparent&amp;embedded=true&amp;f=Arial%252C%2BVerdana%252C%2Bsans-serif&amp;hl=en&amp;htc=%2523666666&amp;id=1BMaboapV0IaS8iGnCJut2obPZ9y3CWkxXuvy-7krcgE&amp;lc=%2523003965&amp;pli=1&amp;tc=%2523444444&amp;ttl=0" target="_blank" rel="noreferrer">CaSS Slack Channel</a> to join the conversation.</p><p>You may also <a href="mailto:cass@eduworks.com" target="_blank" rel="noreferrer">email us</a>.</p>',24)])])}const b=a(o,[["render",n]]);export{u as __pageData,b as default};
